import { NextResponse } from 'next/server';
import { GoogleGenAI } from '@google/genai';

export async function POST(req) {
  try {
    const body = await req.json();
    
    // 1. Unpack variables (supporting both initial compile & chat refinement payloads!)
    const { 
      conversation, 
      appName, 
      features, 
      techStack, 
      designVibe, 
      advancedConstraints, 
      customApiKey, 
      userApiKey, 
      outputFormat, 
      enableRedTeam 
    } = body;

    // Determine which API key to use (User's BYOK takes priority over your server .env key)
    const activeApiKey = customApiKey || userApiKey || process.env.GEMINI_API_KEY;

    if (!activeApiKey) {
      return NextResponse.json({ 
        error: 'No Google Gemini API Key found. Please add GEMINI_API_KEY to your .env.local or connect your BYOK key in settings!' 
      }, { status: 401 });
    }

    // Initialize the Google GenAI client
    const ai = new GoogleGenAI({ apiKey: activeApiKey });

    // 2. Configure the Master System Prompt
    const systemInstruction = outputFormat === 'cursorrules'
      ? `You are an expert Spatial Software Architect and Principal Engineer. Output a hyper-structured, fully complete software specification tailored perfectly as a .cursorrules configuration file for AI IDEs (Cursor, Windsurf, VS Code Copilot). Use clean markdown codeblocks. Do not write conversational introductions or filler text. Start directly with the technical specification.`
      : `You are an expert Spatial Software Architect and Principal Engineer. Synthesize a comprehensive structural development blueprint spanning technical specifications, step-by-step implementation phases, and database layout architectures. Output only raw structured markdown without conversational filler text.`;

    // 3. Build the content payload for Gemini
    let formattedContents = [];

    if (conversation && Array.isArray(conversation) && conversation.length > 0) {
      // MODE A: CONTINUOUS CHAT REFINEMENT
      // Map your React chat history directly into Google's required schema
      formattedContents = conversation.map(msg => ({
        role: msg.role === 'assistant' ? 'model' : 'user',
        parts: [{ text: msg.content }]
      }));
    } else {
      // MODE B: INITIAL WIZARD COMPILE (Fallback if conversation array isn't sent)
      const initialPrompt = `
        SYNTHESIZE MASTER ARCHITECTURAL BLUEPRINT FOR:
        - Project Identity: ${appName || 'Spatial App Concept'}
        - Target Tech Stack: ${techStack || 'Next.js + Tailwind CSS'}
        - State & Persistence: ${advancedConstraints || 'Standard Cloud Architecture'}
        - Aesthetic Direction: ${designVibe || 'Apple VisionOS Frosted Glass'}
        - Specific Requirements & Superpowers:
        ${features || 'Best-practice modern architecture'}
        - Red Team Audit Enabled: ${enableRedTeam ? 'YES (Perform strict failure mode & scalability stress-test audit)' : 'NO'}
      `.trim();

      formattedContents = [{ role: 'user', parts: [{ text: initialPrompt }] }];
    }

    // 4. Trigger Gemini Synthesis
    const response = await ai.models.generateContent({
      model: 'gemini-3.5-flash', // Blazing fast model perfect for live chat iterations
      contents: formattedContents,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.2, // Low temperature keeps code structures strict and accurate
      }
    });

    const finalResult = response.text || '// Specification rendering engine returned an empty string.';

    // Return using 'result' so both handleCompile and handleGenerateOrRefine can read it!
    return NextResponse.json({ result: finalResult });

  } catch (error) {
    console.error('Gemini Backend Processing Failure:', error);
    return NextResponse.json({ 
      error: error.message || 'Failed to process AI architectural synthesis.' 
    }, { status: 500 });
  }
}